import React, { useEffect, useState } from "react";
import logo from "../assests/vighnexlogo.png";
export default function Home() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [activeFaq, setActiveFaq] = useState(0);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollTo = (id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }
  };

  const Icon = ({ type, size = 26 }) => {
    const icons = {
      code: (
        <>
          <path d="M9 18 3 12l6-6" />
          <path d="m15 6 6 6-6 6" />
          <path d="m14 4-4 16" />
        </>
      ),
      design: (
        <>
          <rect x="3" y="3" width="18" height="18" rx="3" />
          <path d="M8 8h8M8 12h5M8 16h8" />
        </>
      ),
      marketing: (
        <>
          <path d="M3 11v2" />
          <path d="M6 9v6" />
          <path d="M9 7v10" />
          <path d="M12 5v14" />
          <path d="M15 8v8" />
          <path d="M18 10v4" />
          <path d="M21 12h.01" />
        </>
      ),
      mobile: (
        <>
          <rect x="6" y="2" width="12" height="20" rx="3" />
          <path d="M10 18h4" />
        </>
      ),
      cloud: (
        <path d="M17.5 19H9a6 6 0 1 1 1.3-11.86A7 7 0 0 1 23 12a4 4 0 0 1-5.5 7Z" />
      ),
      shield: (
        <>
          <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z" />
          <path d="m9 12 2 2 4-5" />
        </>
      ),
      rocket: (
        <>
          <path d="M4.5 16.5c-1.5 1.5-2 4-2 4s2.5-.5 4-2l2-2-2-2-2 2Z" />
          <path d="m14 5 5 5" />
          <path d="M13 4c3-2 7-2 8-1-1 1 0 5-1 7l-7 7-5-5 7-8Z" />
          <circle cx="16" cy="8" r="1" />
        </>
      ),
      target: (
        <>
          <circle cx="12" cy="12" r="9" />
          <circle cx="12" cy="12" r="5" />
          <circle cx="12" cy="12" r="1" />
        </>
      ),
      users: (
        <>
          <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" />
          <circle cx="9" cy="7" r="4" />
          <path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75" />
        </>
      ),
      check: <path d="m5 12 4 4L19 6" />,
      arrow: (
        <>
          <path d="M5 12h14" />
          <path d="m13 6 6 6-6 6" />
        </>
      ),
      star: (
        <path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9L12 3Z" />
      ),
      phone: (
        <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.78.62 2.63a2 2 0 0 1-.45 2.11L8 9.73a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.85.29 1.73.5 2.63.62A2 2 0 0 1 22 16.92Z" />
      ),
      mail: (
        <>
          <rect x="3" y="5" width="18" height="14" rx="2" />
          <path d="m3 7 9 6 9-6" />
        </>
      ),
      location: (
        <>
          <path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z" />
          <circle cx="12" cy="10" r="2.5" />
        </>
      ),
      menu: <path d="M4 6h16M4 12h16M4 18h16" />,
      close: <path d="M6 6l12 12M18 6 6 18" />,
      spark: (
        <>
          <path d="m12 3 1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5L12 3Z" />
          <path d="m19 16 .7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7L19 16Z" />
        </>
      ),
      database: (
        <>
          <ellipse cx="12" cy="5" rx="8" ry="3" />
          <path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5" />
          <path d="M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7" />
        </>
      ),
      layers: (
        <>
          <path d="m12 2 9 5-9 5-9-5 9-5Z" />
          <path d="m3 12 9 5 9-5" />
          <path d="m3 17 9 5 9-5" />
        </>
      ),
      headphones: (
        <>
          <path d="M3 18v-6a9 9 0 0 1 18 0v6" />
          <path d="M21 19a2 2 0 0 1-2 2h-1v-7h3v5ZM3 19a2 2 0 0 0 2 2h1v-7H3v5Z" />
        </>
      ),
    };

    return (
      <svg
        width={size}
        height={size}
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {icons[type] || icons.spark}
      </svg>
    );
  };

  const services = [
    {
      icon: "code",
      title: "Web Development",
      text: "High-performance websites and web platforms engineered for speed, accessibility, scalability and measurable business growth.",
      tags: ["React", "Next.js", "Node.js"],
    },
    {
      icon: "design",
      title: "UI/UX Design",
      text: "Human-centered digital experiences combining research, visual systems, interaction design and conversion-focused interfaces.",
      tags: ["Figma", "Design Systems", "Prototyping"],
    },
    {
      icon: "marketing",
      title: "Digital Marketing",
      text: "Data-led marketing strategies that increase visibility, attract qualified audiences and turn attention into sustainable growth.",
      tags: ["SEO", "Social Media", "Analytics"],
    },
    {
      icon: "mobile",
      title: "Mobile Development",
      text: "Modern Android and iOS applications with intuitive interfaces, secure architecture and reliable performance.",
      tags: ["Android", "iOS", "Cross Platform"],
    },
    {
      icon: "cloud",
      title: "Cloud Development",
      text: "Secure cloud-native solutions designed for resilience, automation, cost efficiency and effortless scaling.",
      tags: ["AWS", "Azure", "DevOps"],
    },
  ];

  const technologies = [
    ["React", "Frontend"],
    ["Next.js", "Frontend"],
    ["Node.js", "Backend"],
    ["Python", "Backend"],
    ["Java", "Backend"],
    ["Flutter", "Mobile"],
    ["MongoDB", "Database"],
    ["PostgreSQL", "Database"],
    ["AWS", "Cloud"],
    ["Docker", "DevOps"],
    ["Figma", "Design"],
    ["GitHub", "Development"],
  ];

  const process = [
    [
      "01",
      "Discover",
      "We understand your goals, audience, challenges and opportunities before writing a single line of code.",
      "target",
    ],
    [
      "02",
      "Strategize",
      "We convert business requirements into a clear digital roadmap with measurable priorities.",
      "layers",
    ],
    [
      "03",
      "Design",
      "We create intuitive interfaces and experiences that feel natural, premium and purposeful.",
      "design",
    ],
    [
      "04",
      "Build",
      "Our engineers transform the approved experience into secure, scalable and high-quality products.",
      "code",
    ],
    [
      "05",
      "Launch",
      "We test, optimize, deploy and monitor your solution for a confident launch.",
      "rocket",
    ],
    [
      "06",
      "Grow",
      "We continue improving your product using data, feedback, experiments and technology.",
      "spark",
    ],
  ];

  const projects = [
    {
      title: "FinEdge",
      category: "FinTech Platform",
      text: "A modern financial management experience designed around clarity, trust and frictionless digital journeys.",
      image:
        "https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1200&q=85",
    },
    {
      title: "Medivista",
      category: "Healthcare Experience",
      text: "A patient-focused digital ecosystem that makes appointments, information and communication easier.",
      image:
        "https://images.unsplash.com/photo-1559757148-5c350d0d3c56?auto=format&fit=crop&w=1200&q=85",
    },
    {
      title: "UrbanCart",
      category: "E-Commerce",
      text: "A conversion-focused shopping experience built for speed, discovery and effortless checkout.",
      image:
        "https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1200&q=85",
    },
  ];

  const testimonials = [
    {
      name: "Ananya Rao",
      role: "Founder, Nova Ventures",
      text: "The Vighnex team understood our vision quickly and turned it into a digital experience that feels far more premium than we imagined.",
      image:
        "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=300&q=80",
    },
    {
      name: "Rahul Mehta",
      role: "Director, Crest Solutions",
      text: "What impressed us most was the combination of design thinking and technical discipline. Communication was clear from start to finish.",
      image:
        "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=80",
    },
    {
      name: "Priya Sharma",
      role: "Entrepreneur",
      text: "They did not simply build a website. They helped us think through our entire digital presence and created something our customers love.",
      image:
        "https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&w=300&q=80",
    },
  ];

  const faqs = [
    [
      "What services does Vighnex Technologies provide?",
      "We provide web development, UI/UX design, digital marketing, mobile application development and cloud development. We can also combine multiple services into one complete digital transformation engagement.",
    ],
    [
      "Can you build a website from an idea only?",
      "Yes. We can start from a concept, business requirement, rough sketch or existing website. We help define the structure, user journey, visual direction, technology and launch plan.",
    ],
    [
      "Do you develop mobile applications for both Android and iOS?",
      "Yes. Depending on project requirements, we can build native or cross-platform applications with a strong focus on performance, security and user experience.",
    ],
    [
      "Do you provide maintenance after launch?",
      "Yes. We can provide ongoing technical support, security updates, performance improvements, content changes, analytics and feature development.",
    ],
    [
      "How do you handle project communication?",
      "We maintain a structured communication process with requirement discussions, progress updates, reviews, testing and final deployment so clients always understand the current project status.",
    ],
    [
      "How can I start a project with Vighnex?",
      "Simply contact us with your idea, requirements or business challenge. We will understand your objectives and discuss the most practical next steps.",
    ],
  ];

  return (
    <div className="site">
      <style>{`
        *{box-sizing:border-box;margin:0;padding:0}
        html{scroll-behavior:smooth}
        body{font-family:Inter,Arial,sans-serif;color:#11243a;background:#faf7f0}
        .site{overflow:hidden;background:#faf7f0}
        :root{--navy:#092338;--navy2:#12344c;--gold:#c89032;--gold2:#e6b85c;--cream:#faf7f0;--white:#fff;--text:#11243a;--muted:#637181}
        .container{width:min(1180px,92%);margin:auto}
        .section{padding:105px 0;position:relative}
        .section-dark{background:linear-gradient(135deg,#071f32,#0d354c);color:white}
        .section-title{text-align:center;max-width:720px;margin:0 auto 60px}
        .eyebrow{display:inline-flex;align-items:center;gap:10px;color:var(--gold);font-size:12px;letter-spacing:4px;font-weight:800;text-transform:uppercase;margin-bottom:14px}
        .eyebrow:before,.eyebrow:after{content:"";height:1px;width:30px;background:currentColor}
        .section-title h2{font-family:Georgia,serif;font-size:clamp(36px,5vw,58px);line-height:1.05;margin-bottom:18px;color:var(--navy)}
        .section-dark .section-title h2{color:white}
        .section-title p{font-size:17px;line-height:1.8;color:var(--muted)}
        .section-dark .section-title p{color:#cbd8e0}
        .btn{border:0;border-radius:50px;padding:15px 25px;font-size:14px;font-weight:800;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:10px;transition:.3s;text-decoration:none}
        .btn-primary{background:var(--navy);color:white;box-shadow:0 12px 28px rgba(9,35,56,.18)}
        .btn-primary:hover{transform:translateY(-3px);background:#153e59}
        .btn-gold{background:linear-gradient(135deg,var(--gold2),var(--gold));color:#152536}
        .btn-gold:hover{transform:translateY(-3px);box-shadow:0 12px 30px rgba(200,144,50,.28)}
        .btn-outline{border:1px solid rgba(255,255,255,.35);color:white;background:transparent}
        .btn-outline:hover{background:white;color:var(--navy)}
        .navbar{position:fixed;left:0;right:0;top:0;height:78px;z-index:1000;display:flex;align-items:center;transition:.3s;background:rgba(250,247,240,.9);backdrop-filter:blur(14px)}
        .navbar.scrolled{box-shadow:0 8px 30px rgba(0,0,0,.08)}
        .nav-inner{display:flex;align-items:center;justify-content:space-between}
        .logo{display:flex;align-items:center;gap:10px;cursor:pointer}
        .logo-image{width:275px;height:82px;object-fit:contain;object-position:left center;display:block}
        .nav-links{display:flex;align-items:center;gap:32px}
        .nav-links button{border:0;background:none;font-weight:700;color:#24384b;cursor:pointer;font-size:14px;position:relative;padding:7px 0}
        .nav-links button:after{content:"";position:absolute;bottom:0;left:50%;width:0;height:2px;background:var(--gold);transition:.3s}
        .nav-links button:hover:after{left:0;width:100%}
        .menu-btn{display:none;background:none;border:0;color:var(--navy);cursor:pointer}
        .hero{min-height:760px;padding-top:150px;padding-bottom:80px;position:relative;background:radial-gradient(circle at 78% 35%,rgba(214,169,78,.2),transparent 32%),linear-gradient(110deg,#faf7f0 40%,#f0e5ce)}
        .hero:before{content:"";position:absolute;width:600px;height:600px;border:1px solid rgba(200,144,50,.18);border-radius:50%;right:-200px;top:120px}
        .hero:after{content:"";position:absolute;width:420px;height:420px;border:1px solid rgba(200,144,50,.15);border-radius:50%;right:-110px;top:210px}
        .hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center;position:relative;z-index:2}
        .hero-copy .eyebrow{margin-bottom:22px}
        .hero h1{font-family:Georgia,serif;font-size:clamp(48px,6.2vw,78px);line-height:.98;color:var(--navy);letter-spacing:-2px}
        .hero h1 span{color:var(--gold)}
        .hero-copy>p{max-width:600px;font-size:18px;line-height:1.75;color:#566575;margin:27px 0 32px}
        .hero-actions{display:flex;gap:14px;flex-wrap:wrap}
        .hero-note{display:flex;align-items:center;gap:12px;margin-top:30px;color:#526274;font-size:13px}
        .hero-note strong{color:var(--navy)}
        .hero-visual{position:relative;min-height:520px;display:flex;align-items:center;justify-content:center}
        .hero-image{width:430px;height:500px;object-fit:cover;border-radius:220px 220px 30px 30px;box-shadow:25px 30px 70px rgba(29,45,58,.2);border:8px solid rgba(255,255,255,.75)}
        .hero-badge{position:absolute;background:white;padding:18px 20px;border-radius:18px;box-shadow:0 15px 40px rgba(20,40,55,.13);display:flex;gap:12px;align-items:center}
        .hero-badge.one{left:0;top:100px}
        .hero-badge.two{right:0;bottom:75px}
        .badge-icon{width:43px;height:43px;border-radius:13px;background:#fff2d4;color:var(--gold);display:grid;place-items:center}
        .badge-text strong{display:block;color:var(--navy);font-size:15px}
        .badge-text span{font-size:11px;color:#7a8792}
        .mandala{position:absolute;width:100px;height:100px;border:2px dashed rgba(200,144,50,.35);border-radius:50%;right:15px;top:25px}
        .about-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
        .about-image-wrap{position:relative}
        .about-image{width:100%;height:540px;object-fit:cover;border-radius:25px;box-shadow:20px 25px 60px rgba(17,36,58,.13)}
        .about-card{position:absolute;right:-25px;bottom:30px;background:var(--navy);color:white;padding:25px;border-radius:20px;width:200px;text-align:center;box-shadow:0 20px 45px rgba(9,35,56,.25)}
        .about-card strong{display:block;font-family:Georgia,serif;font-size:39px;color:var(--gold2)}
        .about-card span{font-size:12px;color:#d5e0e7}
        .about-copy h2{font-family:Georgia,serif;font-size:clamp(38px,5vw,56px);line-height:1.05;color:var(--navy);margin-bottom:22px}
        .about-copy p{font-size:16px;line-height:1.85;color:var(--muted);margin-bottom:17px}
        .values{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin:28px 0}
        .value{padding:17px;border:1px solid #e8decb;border-radius:15px;background:white}
        .value strong{display:block;margin-bottom:5px;color:var(--navy)}
        .value span{font-size:12px;color:var(--muted)}
        .services-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
        .service{background:white;border:1px solid rgba(255,255,255,.15);border-radius:20px;padding:28px 20px;min-height:340px;transition:.35s;position:relative;overflow:hidden}
        .service:before{content:"";position:absolute;width:100px;height:100px;border-radius:50%;background:rgba(200,144,50,.1);right:-40px;top:-40px}
        .service:hover{transform:translateY(-9px);box-shadow:0 20px 45px rgba(0,0,0,.2)}
        .service-icon{width:58px;height:58px;border-radius:17px;display:grid;place-items:center;background:#fff1cf;color:var(--gold);margin-bottom:24px}
        .service h3{font-family:Georgia,serif;font-size:21px;margin-bottom:13px}
        .service p{color:#b7c8d3;font-size:13px;line-height:1.7;margin-bottom:20px}
        .tags{display:flex;flex-wrap:wrap;gap:6px}
        .tag{font-size:10px;border:1px solid #d9e2e8;border-radius:20px;padding:6px 8px;color:#60717f}
        .section-dark .tag{border-color:#355264;color:#d3dfe6}
        .why-grid{display:grid;grid-template-columns:1fr 1fr;gap:75px;align-items:center}
        .why-copy h2{font-family:Georgia,serif;font-size:clamp(38px,5vw,56px);line-height:1.08;margin-bottom:20px}
        .why-copy>p{line-height:1.8;color:#b9cad4;margin-bottom:25px}
        .why-list{display:grid;gap:17px}
        .why-item{display:flex;gap:15px;align-items:flex-start}
        .why-check{width:35px;height:35px;min-width:35px;border-radius:50%;background:rgba(230,184,92,.15);color:var(--gold2);display:grid;place-items:center}
        .why-item strong{display:block;margin-bottom:4px}
        .why-item span{font-size:13px;line-height:1.5;color:#a9bdc9}
        .why-photo{height:580px;object-fit:cover;width:100%;border-radius:30px;box-shadow:0 25px 60px rgba(0,0,0,.2)}
        .tech-wrap{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;max-width:900px;margin:auto}
