        .footer-links button{background:none;border:0;color:#aebec8;text-align:left;cursor:pointer;font-size:12px}
        .footer-links button:hover{color:var(--gold2)}
        .footer-bottom{border-top:1px solid rgba(255,255,255,.1);padding-top:23px;display:flex;justify-content:space-between;gap:20px;font-size:11px}
        .socials{display:flex;gap:8px}
        .social{width:34px;height:34px;border:1px solid #385263;border-radius:50%;display:grid;place-items:center;color:#c4d2d9;text-decoration:none}
        .social:hover{background:var(--gold);color:var(--navy);border-color:var(--gold)}
        .traditional{position:absolute;opacity:.08;pointer-events:none;font-family:Georgia,serif;color:var(--gold);font-size:100px}
        .t1{left:-25px;top:30px}
        .t2{right:-25px;bottom:30px}

        @media(max-width:1050px){
          .services-grid{grid-template-columns:repeat(3,1fr)}
          .process-grid{grid-template-columns:repeat(3,1fr);gap:35px}
          .process:not(:last-child):after{display:none}
        }

        @media(max-width:850px){
          .nav-links{position:absolute;top:78px;left:0;right:0;background:rgba(250,247,240,.98);padding:25px;display:none;flex-direction:column;align-items:stretch;gap:5px;box-shadow:0 20px 30px rgba(0,0,0,.08)}
          .nav-links.open{display:flex}
          .nav-links button{text-align:center;padding:13px}
          .navbar .btn{display:none}
          .menu-btn{display:block}
          .hero{padding-top:120px}
          .hero-grid,.about-grid,.why-grid,.contact-grid{grid-template-columns:1fr;gap:45px}
          .hero-visual{min-height:470px}
          .hero-image{height:450px;width:370px}
          .hero-badge.one{left:0}
          .hero-badge.two{right:0}
          .about-image{height:430px}
          .why-photo{height:450px}
          .projects-grid,.testimonial-grid{grid-template-columns:1fr}
          .stats-grid{grid-template-columns:1fr 1fr}
          .stat{border-right:0;border-bottom:1px solid rgba(255,255,255,.15)}
          .footer-grid{grid-template-columns:1fr 1fr}
        }

        @media(max-width:600px){
          .section{padding:75px 0}
          .hero h1{font-size:48px}
          .hero-copy>p{font-size:15px}
          .hero-visual{min-height:390px}
          .hero-image{height:390px;width:285px}
          .hero-badge{padding:12px}
          .hero-badge.one{left:-5px;top:55px}
          .hero-badge.two{right:-5px;bottom:30px}
          .badge-icon{width:36px;height:36px}
          .badge-text strong{font-size:12px}
          .badge-text span{font-size:9px}
          .services-grid{grid-template-columns:1fr}
          .service{min-height:auto}
          .values{grid-template-columns:1fr}
          .process-grid{grid-template-columns:1fr 1fr}
          .stats-grid{grid-template-columns:1fr 1fr}
          .stat strong{font-size:38px}
          .form-grid{grid-template-columns:1fr}
          .field.full{grid-column:auto}
          .footer-grid{grid-template-columns:1fr}
          .footer-bottom{flex-direction:column}
          .contact-form{padding:24px}
          .logo-image{width:500px;height:406px}
        }
      `}</style>

      <nav className={`navbar ${scrolled ? "scrolled" : ""}`}>
